SELECT "IdEmpresa","Modulo","CodigoParametro","Valor" FROM (SELECT id_empresa AS "IdEmpresa",'PLATAFORMA' AS "Modulo",codigo_parametro AS "CodigoParametro",valor AS "Valor" FROM t_pla_pla_configuracion UNION SELECT id_empresa AS "IdEmpresa",'CONTABILIDAD' AS "Modulo",codigo_parametro AS "CodigoParametro",valor AS "Valor" FROM t_cnt_con_configuracion_contabilidad UNION SELECT id_empresa AS "IdEmpresa",'ORDENES' AS "Modulo",codigo_parametro AS "CodigoParametro",valor AS "Valor" FROM t_ord_ord_configuracion_ordenes UNION SELECT id_empresa AS "IdEmpresa",'CUENTAINVERSION' AS "Modulo",codigo_parametro AS "CodigoParametro",valor AS "Valor" FROM t_ctainver_cta_configuracion_cuenta_inversion UNION SELECT id_empresa AS "IdEmpresa",'TESORERIA' AS "Modulo",codigo_parametro AS "CodigoParametro",valor AS "Valor" FROM t_tes_tes_configuracion_tesoreria UNION SELECT id_empresa AS "IdEmpresa",'FACTURACION' AS "Modulo",codigo_parametro AS "CodigoParametro",valor AS "Valor" FROM t_fac_fac_configuracion_facturacion UNION SELECT id_empresa AS "IdEmpresa",'SOCIODENEGOCIO' AS "Modulo",codigo_parametro AS "CodigoParametro",valor AS "Valor" FROM t_sdn_soc_configuracion_socio_negocio UNION SELECT id_empresa AS "IdEmpresa",'CUSTODIA' AS "Modulo",codigo_parametro AS "CodigoParametro",valor AS "Valor" FROM t_cus_cus_configuracion UNION SELECT id_empresa AS "IdEmpresa",'FONDOMUTUO' AS "Modulo",nombre_tipo_parametro AS "CodigoParametro",valor_parametro AS "Valor" FROM t_fmm_fmm_parametro UNION SELECT id_empresa AS "IdEmpresa",'APV' AS "Modulo",codigo_parametro AS "CodigoParametro",valor AS "Valor" FROM t_apv_pla_configuracion_apv UNION SELECT id_empresa AS "IdEmpresa",'MESA' AS "Modulo",codigo_parametro AS "CodigoParametro",valor AS "Valor" FROM t_mes_mes_configuracion_mesa UNION SELECT id_empresa AS "IdEmpresa",'PRODUCTO' AS "Modulo",codigo_parametro AS "CodigoParametro",valor AS "Valor" FROM t_pla_pro_configuracion) AS q WHERE "IdEmpresa" = :IdEmpresa